def design(feats) -> Design:
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float)
    n, p = X.shape; ids = tuple(feats.ids)
    empty = Design(drivers=(), columns=(), products=(), loadings={})
    if not p or not n or np.unique(y).size < 2 or MAX_DRIVERS < 1: return empty
    labs = list(dict.fromkeys(feats.stratum))
    S = np.column_stack([np.ones(n)] + [np.asarray([s == l for s in feats.stratum], float) for l in labs[1:]])
    A = X - X.mean(0); A /= np.maximum(np.sqrt((A * A).sum(0)), 1e-8)
    R = np.clip(A.T @ A, -1, 1); cache = {}
    def col(t):
        if not isinstance(t, tuple): return X[:, t]
        v = X[:, t[0]] * X[:, t[1]]
        return (v - v.mean()) / max(v.std(), 1e-8)
    def matrix(ts): return np.column_stack([S] + [col(t) for t in ts])
    def fit(ts):
        if tuple(ts) in cache: return cache[tuple(ts)]
        Z = matrix(ts); b = np.zeros(Z.shape[1])
        def loglik(c):
            z = Z @ c
            return float(y @ z - np.logaddexp(0, z).sum())
        value = loglik(b)
        for _ in range(35):
            mu = 1 / (1 + np.exp(-np.clip(Z @ b, -30, 30)))
            w = np.maximum(mu * (1 - mu), 1e-8)
            H = Z.T @ (w[:, None] * Z) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - mu)); rate = 1.0
            while rate > 1e-6 and loglik(b + rate * step) < value - 1e-9: rate *= 0.5
            b += rate * step; new = loglik(b)
            if abs(new - value) < 1e-8: break
            value = new
        ans = (loglik(b), 1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))))
        cache[tuple(ts)] = ans; return ans
    degree = (abs(R) >= 0.6).sum(0) - 1
    hubs = [int(j) for j in np.argsort(-degree) if feats.types[j] == 'clinical' and degree[j] >= 3][:3]
    def gain(j, sel):
        base = list(dict.fromkeys(list(sel) + [h for h in hubs if h != j]))
        return max(0., 2 * (fit(base + [j])[0] - fit(base)[0]))
    sel = []
    for k in range(min(6, MAX_DRIVERS)):
        cand = [j for j in range(p) if j not in sel and all(abs(R[j, s]) < 0.6 for s in sel)]
        if not cand: break
        gains = [gain(j, sel) for j in cand]; j = cand[int(np.argmax(gains))]
        if stats.chi2.sf(max(gains), 1) > (0.15 if k < 2 else 0.05) / p: break
        C = [j] + [c for c in range(p) if abs(R[j, c]) >= 0.6]
        if len(C) > 1:
            gu = {m: max(0., 2 * (fit([m])[0] - fit([])[0])) for m in C}
            ok = [m for m in C if gu[m] >= max(gu.values()) - 3]
            clin = [m for m in ok if feats.types[m] == 'clinical']
            j = min(clin or ok, key=lambda m: (sum(max(0., 2 * (fit([m, c])[0] - fit([m])[0])) for c in C if c != m), -gu[m]))
        sel.append(j)
    for j in list(reversed(sel)):
        if stats.chi2.sf(max(0., 2 * (fit(sel)[0] - fit([s for s in sel if s != j])[0])), 1) > 0.05 / p: sel.remove(j)
    base = list(dict.fromkeys(sel + hubs)); Z = matrix(base); mu = fit(base)[1]
    w = np.maximum(mu * (1 - mu), 1e-8); resid = y - mu; Hinv = np.linalg.pinv(Z.T @ (w[:, None] * Z))
    pairs = [(i, j) for i in range(p) for j in range(i, p)]; scores = []
    for pair in pairs:
        u = col(pair); cross = Z.T @ (w * u)
        var = max(float(u @ (w * u) - cross @ Hinv @ cross), 1e-8)
        scores.append(float(u @ resid) ** 2 / var)
    prods = []
    for idx in np.argsort(scores)[::-1][:25]:
        i, j = pairs[idx]; mains = list(dict.fromkeys(base + [i, j]))
        lr = max(0., 2 * (fit(mains + [(i, j)])[0] - fit(mains)[0]))
        if stats.chi2.sf(lr, 1) >= 0.005 / len(pairs): continue
        if any((abs(R[i, a]) > 0.95 and abs(R[j, b]) > 0.95) or (abs(R[i, b]) > 0.95 and abs(R[j, a]) > 0.95) for a, b in prods): continue
        prods.append((i, j))
        if len(prods) == 2: break
    terms = list(dict.fromkeys(base + [j for pair in prods for j in pair])) + prods
    strengths = {j: gain(j, [s for s in sel if s != j]) for j in sel}
    if prods:
        strengths = {j: max(0., 2 * (fit(terms)[0] - fit([t for t in terms if t != j])[0])) for j in sel}
        strengths = {j: g for j, g in strengths.items() if stats.chi2.sf(g, 1) < 0.05 / p}
    for i, j in prods:
        lr = max(0., 2 * (fit(terms)[0] - fit([t for t in terms if t != (i, j)])[0]))
        for m in (i, j): strengths[m] = max(strengths.get(m, 0.), lr)
    drivers = sorted(strengths, key=lambda j: -strengths[j])[:MAX_DRIVERS]
    if not drivers: return empty
    columns = list(dict.fromkeys(sel + hubs + [j for pair in prods for j in pair]))
    return Design(drivers=tuple(ids[j] for j in drivers), columns=tuple(ids[j] for j in columns),
                  products=tuple((ids[i], ids[j]) for i, j in prods), loadings={})

